 54	package br.com.marealta.api;
 55	
 56	import br.com.marealta.domain.*;
 57	import br.com.marealta.report.*;
 58	import br.com.marealta.repository.*;
 59	import br.com.marealta.service.*;
 60	import com.fasterxml.jackson.databind.ObjectMapper;
 61	import com.fasterxml.jackson.databind.node.ArrayNode;
 62	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 63	import io.javalin.Javalin;
 64	import io.javalin.http.Context;
 65	
 66	import java.time.LocalDate;
 67	import java.time.YearMonth;
 68	import java.util.List;
 69	
 70	public class RestApi {
 71	    private final RoomRepository roomRepository;
 72	    private final ReservationRepository reservationRepository;
 73	    private final MessageRepository messageRepository;
 74	    private final ReservationService reservationService;
 75	    private final MessageService messageService;
 76	    private final ObjectMapper objectMapper;
 77	    private final ApiMapper apiMapper;
 78	
 79	    public RestApi(RoomRepository roomRepository,
 80	                   ReservationRepository reservationRepository,
 81	                   MessageRepository messageRepository,
 82	                   ReservationService reservationService,
 83	                   MessageService messageService) {
 84	        this.roomRepository = roomRepository;
 85	        this.reservationRepository = reservationRepository;
 86	        this.messageRepository = messageRepository;
 87	        this.reservationService = reservationService;
 88	        this.messageService = messageService;
 89	        this.objectMapper = new ObjectMapper();
 90	        this.objectMapper.registerModule(new JavaTimeModule());
 91	        this.apiMapper = new ApiMapper(objectMapper);
 92	    }
 93	
 94	    public Javalin createApp() {
 95	        Javalin app = Javalin.create();
 96	
 97	        app.get("/rooms", this::getRooms);
 98	        app.post("/reservations", this::createReservation);
 99	        app.get("/reservations/{id}", this::getReservation);
100	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
101	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
102	        app.post("/reservations/{id}/check-in", this::checkIn);
103	        app.post("/reservations/{id}/check-out", this::checkOut);
104	        app.get("/reservations/{id}/document", this::getDocument);
105	        app.get("/messages", this::getMessages);
106	        app.get("/reports/occupancy", this::getOccupancyReport);
107	        app.get("/reports/revenue", this::getRevenueReport);
108	        app.get("/reports/tourism-tax", this::getTourismTaxReport);
109	        app.get("/reports/rate-plans", this::getRatePlansReport);
110	
111	        app.exception(ApiMapper.InvalidRequestException.class, (e, ctx) -> {
112	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
113	        });
114	
115	        app.exception(ReservationService.RoomNotFoundException.class, (e, ctx) -> {
116	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
117	        });
118	
119	        app.exception(ReservationService.ReservationNotFoundException.class, (e, ctx) -> {
120	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
121	        });
122	
123	        app.exception(ReservationService.RoomUnavailableException.class, (e, ctx) -> {
124	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
125	        });
126	
127	        app.exception(ReservationService.OperationNotAllowedException.class, (e, ctx) -> {
128	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for this reservation status"));
129	        });
130	
131	        app.exception(ReservationService.CapacityExceededException.class, (e, ctx) -> {
132	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
133	        });
134	
135	        return app;
136	    }
137	
138	    private void getRooms(Context ctx) {
139	        List<Room> rooms = roomRepository.findAll();
140	        ArrayNode array = objectMapper.createArrayNode();
141	        for (Room room : rooms) {
142	            array.add(apiMapper.mapRoom(room));
143	        }
144	        ctx.json(array);
145	    }
146	
147	    private void createReservation(Context ctx) {
148	        ApiMapper.CreateReservationRequest request =
149	                apiMapper.parseCreateReservationRequest(ctx.body());
150	
151	        Reservation reservation = reservationService.createReservation(
152	                request.roomNumber(),
153	                request.guestName(),
154	                request.guestEmail(),
155	                request.guestCpf(),
156	                request.checkIn(),
157	                request.checkOut(),
158	                request.guests(),
159	                request.ratePlan()
160	        );
161	
162	        ctx.status(201).json(apiMapper.mapReservation(reservation));
163	    }
164	
165	    private void getReservation(Context ctx) {
166	        Long id = Long.parseLong(ctx.pathParam("id"));
167	        Reservation reservation = reservationService.getReservation(id);
168	        ctx.json(apiMapper.mapReservation(reservation));
169	    }
170	
171	    private void confirmReservation(Context ctx) {
172	        Long id = Long.parseLong(ctx.pathParam("id"));
173	        Reservation reservation = reservationService.confirmReservation(id);
174	        ctx.json(apiMapper.mapReservation(reservation));
175	    }
176	
177	    private void cancelReservation(Context ctx) {
178	        Long id = Long.parseLong(ctx.pathParam("id"));
179	        Reservation reservation = reservationService.cancelReservation(id);
180	        ctx.json(apiMapper.mapReservation(reservation));
181	    }
182	
183	    private void checkIn(Context ctx) {
184	        Long id = Long.parseLong(ctx.pathParam("id"));
185	        Reservation reservation = reservationService.checkIn(id);
186	        ctx.json(apiMapper.mapReservation(reservation));
187	    }
188	
189	    private void checkOut(Context ctx) {
190	        Long id = Long.parseLong(ctx.pathParam("id"));
191	        Document document = reservationService.checkOut(id);
192	        ctx.json(apiMapper.mapDocument(document));
193	    }
194	
195	    private void getDocument(Context ctx) {
196	        Long id = Long.parseLong(ctx.pathParam("id"));
197	        Document document = reservationService.getDocument(id);
198	        ctx.json(apiMapper.mapDocument(document));
199	    }
200	
201	    private void getMessages(Context ctx) {
202	        List<Message> messages = messageService.getAllMessages();
203	        ArrayNode array = objectMapper.createArrayNode();
204	        for (Message message : messages) {
205	            array.add(apiMapper.mapMessage(message));
206	        }
207	        ctx.json(array);
208	    }
209	
210	    private void getOccupancyReport(Context ctx) {
211	        String dateParam = ctx.queryParam("date");
212	        if (dateParam == null) {
213	            throw new ApiMapper.InvalidRequestException("Missing date parameter");
214	        }
215	        LocalDate date = apiMapper.parseDate(dateParam);
216	        CsvReport report = new OccupancyReport(date, reservationRepository, roomRepository);
217	        ctx.contentType("text/csv; charset=utf-8").result(report.generate());
218	    }
219	
220	    private void getRevenueReport(Context ctx) {
221	        String monthParam = ctx.queryParam("month");
222	        if (monthParam == null) {
223	            throw new ApiMapper.InvalidRequestException("Missing month parameter");
224	        }
225	        YearMonth month = apiMapper.parseMonth(monthParam);
226	        CsvReport report = new RevenueReport(month, reservationRepository);
227	        ctx.contentType("text/csv; charset=utf-8").result(report.generate());
228	    }
229	
230	    private void getTourismTaxReport(Context ctx) {
231	        String monthParam = ctx.queryParam("month");
232	        if (monthParam == null) {
233	            throw new ApiMapper.InvalidRequestException("Missing month parameter");
234	        }
235	        YearMonth month = apiMapper.parseMonth(monthParam);
236	        CsvReport report = new TourismTaxReport(month, reservationRepository);
237	        ctx.contentType("text/csv; charset=utf-8").result(report.generate());
238	    }
239	
240	    private void getRatePlansReport(Context ctx) {
241	        String monthParam = ctx.queryParam("month");
242	        if (monthParam == null) {
243	            throw new ApiMapper.InvalidRequestException("Missing month parameter");
244	        }
245	        YearMonth month = apiMapper.parseMonth(monthParam);
246	        CsvReport report = new RatePlanReport(month, reservationRepository);
247	        ctx.contentType("text/csv; charset=utf-8").result(report.generate());
248	    }
249	}

