  1	package br.com.marealta.report;
  2	
  3	import java.util.List;
  4	
  5	public abstract class CsvReport {
  6	    private static final String POUSADA_NAME = "Pousada Maré Alta";
  7	
  8	    public final String generate() {
  9	        StringBuilder csv = new StringBuilder();
 10	        csv.append(buildTitleLine()).append("\n");
 11	        csv.append(buildHeaderLine()).append("\n");
 12	        for (String dataLine : buildDataLines()) {
 13	            csv.append(dataLine).append("\n");
 14	        }
 15	        csv.append(buildTotalLine()).append("\n");
 16	        return csv.toString();
 17	    }
 18	
 19	    protected String buildTitleLine() {
 20	        return POUSADA_NAME + "," + getReportName() + "," + getPeriod();
 21	    }
 22	
 23	    protected abstract String getReportName();
 24	
 25	    protected abstract String getPeriod();
 26	
 27	    protected abstract String buildHeaderLine();
 28	
 29	    protected abstract List<String> buildDataLines();
 30	
 31	    protected abstract String buildTotalLine();
 32	}
 33	package br.com.marealta.report;
 34	
 35	import br.com.marealta.domain.Reservation;
 36	import br.com.marealta.domain.Room;
 37	import br.com.marealta.repository.ReservationRepository;
 38	import br.com.marealta.repository.RoomRepository;
 39	
 40	import java.time.LocalDate;
 41	import java.time.format.DateTimeFormatter;
 42	import java.util.ArrayList;
 43	import java.util.List;
 44	
 45	public class OccupancyReport extends CsvReport {
 46	    private final LocalDate date;
 47	    private final ReservationRepository reservationRepository;
 48	    private final RoomRepository roomRepository;
 49	    private final DateTimeFormatter dateFormatter = DateTimeFormatter.ISO_LOCAL_DATE;
 50	
 51	    public OccupancyReport(LocalDate date, ReservationRepository reservationRepository,
 52	                          RoomRepository roomRepository) {
 53	        this.date = date;
 54	        this.reservationRepository = reservationRepository;
 55	        this.roomRepository = roomRepository;
 56	    }
 57	
 58	    @Override
 59	    protected String getReportName() {
 60	        return "occupancy";
 61	    }
 62	
 63	    @Override
 64	    protected String getPeriod() {
 65	        return date.format(dateFormatter);
 66	    }
 67	
 68	    @Override
 69	    protected String buildHeaderLine() {
 70	        return "room,type,reservation,check_in,check_out";
 71	    }
 72	
 73	    @Override
 74	    protected List<String> buildDataLines() {
 75	        List<Reservation> reservations = reservationRepository.findPaidByDate(date);
 76	        List<String> lines = new ArrayList<>();
 77	
 78	        for (Reservation reservation : reservations) {
 79	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
 80	            lines.add(String.join(",",
 81	                    String.valueOf(room.getNumber()),
 82	                    room.getType().name(),
 83	                    String.valueOf(reservation.getId()),
 84	                    reservation.getCheckIn().format(dateFormatter),
 85	                    reservation.getCheckOut().format(dateFormatter)
 86	            ));
 87	        }
 88	
 89	        return lines;
 90	    }
 91	
 92	    @Override
 93	    protected String buildTotalLine() {
 94	        List<Reservation> reservations = reservationRepository.findPaidByDate(date);
 95	        int totalRooms = roomRepository.findAll().size();
 96	        return "total," + reservations.size() + "/" + totalRooms;
 97	    }
 98	}
