 25	package br.com.marealta.service;
 26	
 27	import br.com.marealta.domain.Document;
 28	import br.com.marealta.domain.Message;
 29	import br.com.marealta.repository.MessageRepository;
 30	
 31	import java.math.BigDecimal;
 32	import java.text.NumberFormat;
 33	import java.time.LocalDate;
 34	import java.time.format.DateTimeFormatter;
 35	import java.util.List;
 36	import java.util.Locale;
 37	
 38	public class MessageService {
 39	    private final MessageRepository messageRepository;
 40	    private final NumberFormat currencyFormat;
 41	    private final DateTimeFormatter dateFormatter;
 42	
 43	    public MessageService(MessageRepository messageRepository) {
 44	        this.messageRepository = messageRepository;
 45	        this.currencyFormat = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
 46	        this.dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 47	    }
 48	
 49	    public void sendConfirmationEmail(String email, String guestName, Document document) {
 50	        String subject = "Reserva confirmada - Pousada Maré Alta";
 51	        String body = buildConfirmationEmail(guestName, document);
 52	        Message message = new Message(null, "EMAIL", email, subject, body);
 53	        messageRepository.save(message);
 54	    }
 55	
 56	    private String buildConfirmationEmail(String guestName, Document document) {
 57	        StringBuilder sb = new StringBuilder();
 58	        sb.append("Olá, ").append(guestName).append("!\n\n");
 59	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
 60	        sb.append(formatDocument(document));
 61	        sb.append("\nA entrada é a partir das 14h, e a saída, até as 12h.\n");
 62	        sb.append("Até breve!");
 63	        return sb.toString();
 64	    }
 65	
 66	    public String formatDocument(Document document) {
 67	        StringBuilder sb = new StringBuilder();
 68	        sb.append(document.getTitle()).append(" nº ").append(document.getReservationId()).append("\n");
 69	        sb.append("Hóspede: ").append(document.getGuestName())
 70	                .append(" (CPF ").append(formatCpf(document.getGuestCpf())).append(")\n");
 71	        sb.append("Quarto: ").append(document.getRoomNumber())
 72	                .append(" (").append(document.getRoomType().name()).append(")\n");
 73	        sb.append("Entrada: ").append(formatDate(document.getCheckIn()))
 74	                .append(" | Saída: ").append(formatDate(document.getCheckOut()))
 75	                .append(" | ").append(document.getNights()).append(document.getNights() == 1 ? " diária" : " diárias").append("\n");
 76	        sb.append("Diárias: ").append(formatCurrency(document.getSubtotal())).append("\n");
 77	        if (document.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 78	            sb.append("Desconto: ").append(formatCurrency(document.getDiscount())).append("\n");
 79	        }
 80	        sb.append("Total: ").append(formatCurrency(document.getTotal()));
 81	        return sb.toString();
 82	    }
 83	
 84	    public List<Message> getAllMessages() {
 85	        return messageRepository.findAll();
 86	    }
 87	
 88	    private String formatCurrency(BigDecimal amount) {
 89	        return currencyFormat.format(amount);
 90	    }
 91	
 92	    private String formatDate(LocalDate date) {
 93	        return date.format(dateFormatter);
 94	    }
 95	
 96	    private String formatCpf(String cpf) {
 97	        if (cpf.length() == 11) {
 98	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
 99	                    cpf.substring(6, 9) + "-" + cpf.substring(9);
100	        }
101	        return cpf;
102	    }
103	}
