123	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
124	        BigDecimal subtotal = BigDecimal.ZERO;
125	        LocalDate current = checkIn;
126	        while (current.isBefore(checkOut)) {
127	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
128	            subtotal = subtotal.add(nightPrice);
129	            current = current.plusDays(1);
130	        }
131	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
132	    }
133	
134	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
135	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
136	            return subtotal.multiply(NON_REFUNDABLE_MULTIPLIER.subtract(BigDecimal.ONE).abs())
137	                    .setScale(2, RoundingMode.HALF_EVEN);
138	        }
139	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
140	    }
