 13	
 14	public class ApiMapper {
 15	    private final ObjectMapper objectMapper;
 16	
 17	    public ApiMapper(ObjectMapper objectMapper) {
 18	        this.objectMapper = objectMapper;
 19	    }
 20	
 21	    public ObjectNode mapRoom(Room room) {
 22	        ObjectNode node = objectMapper.createObjectNode();
 23	        node.put("number", room.getNumber());
 24	        node.put("type", room.getType().name());
 25	        node.put("capacity", room.getCapacity());
 26	        node.put("nightlyRate", room.getNightlyRate());
 27	        return node;
 28	    }
 29	
 30	    public ObjectNode mapReservation(Reservation reservation) {
 31	        ObjectNode node = objectMapper.createObjectNode();
 32	        node.put("id", reservation.getId());
 33	        node.put("roomNumber", reservation.getRoomNumber());
 34	        node.put("guestName", reservation.getGuestName());
 35	        node.put("guestEmail", reservation.getGuestEmail());
 36	        node.put("guestCpf", reservation.getGuestCpf());
 37	        node.put("checkIn", reservation.getCheckIn().toString());
 38	        node.put("checkOut", reservation.getCheckOut().toString());
 39	        node.put("guests", reservation.getGuests());
 40	        node.put("ratePlan", reservation.getRatePlan().name());
 41	        node.put("nights", reservation.getNights());
 42	        node.put("subtotal", reservation.getSubtotal());
 43	        node.put("discount", reservation.getDiscount());
 44	        node.put("total", reservation.getTotal());
 45	        node.put("status", reservation.getStatus().name());
 46	        node.put("amountPaid", reservation.getAmountPaid());
 47	        if (reservation.getRefund() != null) {
 48	            node.put("refund", reservation.getRefund());
 49	        } else {
 50	            node.putNull("refund");
 51	        }
 52	        return node;
 53	    }
 54	
 55	    public ObjectNode mapDocument(Document document) {
 56	        ObjectNode node = objectMapper.createObjectNode();
 57	        node.put("title", document.getTitle());
 58	        node.put("reservationId", document.getReservationId());
 59	        node.put("guestName", document.getGuestName());
 60	        node.put("guestCpf", document.getGuestCpf());
 61	        node.put("roomNumber", document.getRoomNumber());
 62	        node.put("roomType", document.getRoomType().name());
 63	        node.put("checkIn", document.getCheckIn().toString());
 64	        node.put("checkOut", document.getCheckOut().toString());
 65	        node.put("nights", document.getNights());
 66	        node.put("subtotal", document.getSubtotal());
 67	        node.put("discount", document.getDiscount());
 68	        node.put("total", document.getTotal());
 69	        return node;
 70	    }
