 72	    public ObjectNode mapMessage(Message message) {
 73	        ObjectNode node = objectMapper.createObjectNode();
 74	        node.put("id", message.getId());
 75	        node.put("channel", message.getChannel());
 76	        node.put("to", message.getTo());
