  3	import com.zaxxer.hikari.HikariConfig;
  4	import com.zaxxer.hikari.HikariDataSource;
  5	
  6	import javax.sql.DataSource;
  7	import java.sql.Connection;
  8	import java.sql.SQLException;
  9	import java.sql.Statement;
 10	
 11	public class Database {
 12	    private final HikariDataSource dataSource;
 13	
 14	    public Database(String url, String user, String password) {
 15	        HikariConfig config = new HikariConfig();
 16	        config.setJdbcUrl(url);
 17	        config.setUsername(user);
 18	        config.setPassword(password);
 19	        config.setMaximumPoolSize(10);
 20	        this.dataSource = new HikariDataSource(config);
 21	        runMigrations();
 22	    }
 23	
 24	    public DataSource getDataSource() {
 25	        return dataSource;
 26	    }
 27	
 28	    public Connection getConnection() throws SQLException {
 29	        return dataSource.getConnection();
 30	    }
 31	
 32	    private void runMigrations() {
 33	        try (Connection conn = getConnection(); Statement stmt = conn.createStatement()) {
 34	            stmt.execute("""
 35	                CREATE TABLE IF NOT EXISTS rooms (
 36	                    number INT PRIMARY KEY,
 37	                    type VARCHAR(20) NOT NULL
 38	                )
 39	                """);
 40	
 41	            stmt.execute("""
 42	                CREATE TABLE IF NOT EXISTS reservations (
 43	                    id BIGSERIAL PRIMARY KEY,
 44	                    room_number INT NOT NULL,
 45	                    guest_name VARCHAR(255) NOT NULL,
 46	                    guest_email VARCHAR(255) NOT NULL,
 47	                    guest_cpf VARCHAR(14) NOT NULL,
 48	                    check_in DATE NOT NULL,
 49	                    check_out DATE NOT NULL,
 50	                    guests INT NOT NULL,
 51	                    rate_plan VARCHAR(20) NOT NULL,
 52	                    nights INT NOT NULL,
 53	                    subtotal DECIMAL(10, 2) NOT NULL,
 54	                    discount DECIMAL(10, 2) NOT NULL,
 55	                    total DECIMAL(10, 2) NOT NULL,
 56	                    status VARCHAR(20) NOT NULL,
 57	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
 58	                    refund DECIMAL(10, 2)
 59	                )
 60	                """);
 61	
 62	            stmt.execute("""
 63	                CREATE TABLE IF NOT EXISTS messages (
 64	                    id BIGSERIAL PRIMARY KEY,
 65	                    channel VARCHAR(20) NOT NULL,
 66	                    recipient VARCHAR(255) NOT NULL,
 67	                    subject VARCHAR(500) NOT NULL,
 68	                    body TEXT NOT NULL
 69	                )
 70	                """);
 71	        } catch (SQLException e) {
 72	            throw new RuntimeException("Failed to run migrations", e);
 73	        }
 74	    }
 75	
 76	    public void close() {
 77	        if (dataSource != null) {
 78	            dataSource.close();
 79	        }
 80	    }
 81	}
